  name: 'Test: Menu, Search And Result Flow',
  args: {
    showUser: false,
    showLogin: false,
    showSearch: true,
    showMenuButton: true,
    setPage: fn(),
    children: <nav aria-label="Utvidet meny">
        <a href="#aktiviteter">Aktiviteter</a>
      </nav>
  },
  play: async ({
    canvasElement,
    args
  }) => {
    const canvas = within(canvasElement);
    const menuButton = canvas.getByRole('button', {
      name: /meny/i
    });
    const searchButton = canvas.getByRole('button', {
      name: /søk/i
    });
    await userEvent.click(menuButton);
    await waitFor(() => {
      expect(menuButton).toHaveAttribute('aria-expanded', 'true');
      expect(canvas.getByRole('navigation', {
        name: 'Utvidet meny'
      })).toBeVisible();
    });
    await userEvent.click(searchButton);
    await waitFor(() => {
      expect(menuButton).toHaveAttribute('aria-expanded', 'false');
      expect(searchButton).toHaveAttribute('aria-expanded', 'true');
      expect(canvas.queryByRole('navigation', {
        name: 'Utvidet meny'
      })).not.toBeInTheDocument();
    });
    const input = canvas.getByRole('searchbox', {
      name: /søk/i
    });
    await userEvent.type(input, 'Dialog');
    const result = await canvas.findByRole('button', {
      name: 'Dialog'
    });
    await userEvent.click(result);
    expect(args.setPage).toHaveBeenCalledTimes(1);
    // Deep link: a component suggestion navigates to that component's spot
    // in the catalogue, not the catalogue root.
    expect(args.setPage).toHaveBeenCalledWith('components/dialog');
    await waitFor(() => {
      expect(searchButton).toHaveAttribute('aria-expanded', 'false');
      expect(canvas.queryByRole('searchbox', {
        name: /søk/i
      })).not.toBeInTheDocument();
    });
  }
